  #endif
  LA(x9, scof_evw)
  RVMODEL_MHPMEVENT_CODE(x9, x8)
  // stop counting: set every xINH bit (OF and the event are kept)
  #if __riscv_xlen == 64
  AI_LOAD(a1)
  RVTEST_TSBI_CSR_ACCESS TSBI_CSR_SET(RVTEST_CSR_MHPMEVENT)
  #endif
  #if __riscv_xlen == 32
  AI_LOAD(a1)
  RVTEST_TSBI_CSR_ACCESS TSBI_CSR_SET(RVTEST_CSR_MHPMEVENTH)
  #endif
mhpmevent_of_bit_set_of_1:
  #if __riscv_xlen == 64
  RVTEST_TSBI_CSR_ACCESS TSBI_CSR_READ(RVTEST_CSR_MHPMEVENT)
  srli x6, a0, 63
  #endif
  #if __riscv_xlen == 32
  RVTEST_TSBI_CSR_ACCESS TSBI_CSR_READ(RVTEST_CSR_MHPMEVENTH)
  srli x6, a0, 31
  #endif
  AI_CHECK(x6, mhpmevent_of_bit_set_of_1, mhpmevent_of_bit_set_of_1_s0)
mhpmevent_of_bit_set_only_2:
  RVTEST_TSBI_CSR_ACCESS TSBI_CSR_READ(CSR_SCOUNTOVF)
  mv x6, a0
  LI(x7, -8)
  and x6, x6, x7
  AI_CHECK(x6, mhpmevent_of_bit_set_only_2, mhpmevent_of_bit_set_only_2_s1)
  LA(x9, scof_scr)
  LREG x8, 14*REGWIDTH(x9)
  beqz x8, mhpmevent_of_bit_set_mpath_7
  LI(x9, 500)
mhpmevent_of_bit_set_wait_4:
  csrr x8, sip
  srli x8, x8, 13
  andi x8, x8, 1
  bnez x8, mhpmevent_of_bit_set_waitdone_5
  addi x9, x9, -1
  bnez x9, mhpmevent_of_bit_set_wait_4
  j mhpmevent_of_bit_set_waitdone_5
mhpmevent_of_bit_set_mpath_7:
  LI(x9, 50)
mhpmevent_of_bit_set_mwait_6:
  RVTEST_TSBI_CSR_ACCESS TSBI_CSR_READ(CSR_MIP)
  srli x8, a0, 13
  andi x8, x8, 1
  bnez x8, mhpmevent_of_bit_set_waitdone_5
  addi x9, x9, -1
  bnez x9, mhpmevent_of_bit_set_mwait_6
mhpmevent_of_bit_set_waitdone_5:
mhpmevent_of_bit_set_lcofip_3:
  AI_CHECK(x8, mhpmevent_of_bit_set_lcofip_3, mhpmevent_of_bit_set_lcofip_3_s2)
  LI(x6, 8192)
  csrc sie, x6
  csrc sip, x6
  LI(a1, 8192)
  RVTEST_TSBI_CSR_ACCESS TSBI_CSR_CLEAR(CSR_MIE)
  LI(a1, 8192)
  RVTEST_TSBI_CSR_ACCESS TSBI_CSR_CLEAR(CSR_MIP)
  #endif
  LA(x9, scof_scr)
  LREG a1, 8*REGWIDTH(x9)
  RVTEST_TSBI_CSR_ACCESS TSBI_CSR_WRITE(CSR_MCOUNTINHIBIT)

  // teardown: counter frozen, OF=0, event 0, counter 0
  // mhpmevent = all xINH
  #if __riscv_xlen == 64
  AI_LOAD(a1)  // mhpmevent bits 63:32
  RVTEST_TSBI_CSR_ACCESS TSBI_CSR_WRITE(RVTEST_CSR_MHPMEVENT)
  #endif
  #if __riscv_xlen == 32
  LI(a1, 0)
  RVTEST_TSBI_CSR_ACCESS TSBI_CSR_WRITE(RVTEST_CSR_MHPMEVENT)
  AI_LOAD(a1)  // mhpmeventh
  RVTEST_TSBI_CSR_ACCESS TSBI_CSR_WRITE(RVTEST_CSR_MHPMEVENTH)
  #endif
  #if __riscv_xlen == 64
  AI_LOAD(a1)  // 0
  RVTEST_TSBI_CSR_ACCESS TSBI_CSR_WRITE(RVTEST_CSR_MHPMCOUNTER)
  #endif
  #if __riscv_xlen == 32
  AI_LOAD(a1)  // 0 (high half)
  RVTEST_TSBI_CSR_ACCESS TSBI_CSR_WRITE(RVTEST_CSR_MHPMCOUNTERH)
  AI_LOAD(a1)  // 0 (low half)
  RVTEST_TSBI_CSR_ACCESS TSBI_CSR_WRITE(RVTEST_CSR_MHPMCOUNTER)
  #endif
  LI(x6, 8192)
  csrc sie, x6
  csrc sip, x6
  LI(a1, 8192)
  RVTEST_TSBI_CSR_ACCESS TSBI_CSR_CLEAR(CSR_MIE)
  LI(a1, 8192)
  RVTEST_TSBI_CSR_ACCESS TSBI_CSR_CLEAR(CSR_MIP)

RVTEST_CODE_END

